/* The tables of M34 · Health and clinic. */

/** One per student. */
export const healthProfiles = defineTable(
  'health_profiles',
  { module: 'M34', scope: 'org', cap: 'health', family: 'studentId' },
  {
    ...baseColumns,
    studentId: uuid()
      .references((): AnyPgColumn => students.id)
      .notNull(),
    /** `{ substance, reaction, severity: mild \ | moderate \ | severe }[]` */
    allergies: jsonb().notNull().default([]),
    /** `{ name, since?, note? }[]`: asthma, diabetes, epilepsy */
    conditions: jsonb().notNull().default([]),
    /** `{ name, dose, when }[]` */
    regularMedicines: jsonb().notNull().default([]),
    disabilities: text(),
    dietaryNeeds: text(),
    visionNote: text(),
    hearingNote: text(),
    familyDoctorName: text(),
    familyDoctorPhone: text(),
    /** consent to first aid and to being taken to hospital */
    emergencyConsent: enumText(healthProfileEmergencyConsents).notNull().default('not_asked'),
    /** the guardian */
    consentBy: uuid().references((): AnyPgColumn => profiles.id),
    consentAt: timestamptz(),
    /** when the nurse last confirmed it with the family */
    reviewedOn: dateStr(),
    /** for the nurse only */
    note: text(),
  },
  (t) => [uniqueIndex('health_profiles_student_uq').on(t.studentId).where(live(t))],
);

export const clinicVisits = defineTable(
  'clinic_visits',
  {
    module: 'M34',
    scope: 'branch',
    cap: 'health',
    capOwner: 'staffId',
    family: 'studentId',
    familyRule: { read: { shareWithFamily: true } },
  },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    /** from the `clinic_visit` sequence */
    visitNo: text().notNull(),
    /** one of student and staff is required */
    studentId: uuid().references((): AnyPgColumn => students.id),
    staffId: uuid().references((): AnyPgColumn => staff.id),
    arrivedAt: timestamptz().notNull(),
    leftAt: timestamptz(),
    /** the teacher who sent them */
    sentByStaffId: uuid().references((): AnyPgColumn => staff.id),
    complaint: text().notNull(),
    temperatureC: decimal(4, 1),
    /** pulse, blood pressure, oxygen */
    vitals: jsonb().notNull().default({}),
    assessment: text(),
    treatment: text(),
    /** optional until closed */
    outcome: enumText(clinicVisitOutcomes),
    guardianInformedAt: timestamptz(),
    /** when sent home */
    gatePassId: uuid().references((): AnyPgColumn => gatePasses.id),
    followUpOn: dateStr(),
    attendedBy: uuid()
      .references((): AnyPgColumn => profiles.id)
      .notNull(),
    shareWithFamily: boolean().notNull().default(true),
    status: enumText(clinicVisitStatuses).notNull().default('open'),
  },
  (t) => [
    check('clinic_visits_left_at_after', sql`${t.leftAt} > ${t.arrivedAt}`),
    between('clinic_visits', t.temperatureC, 30, 45),
    index('clinic_visits_branch_arrived_at_idx').on(t.orgId, t.branchId, t.arrivedAt),
    index('clinic_visits_student_arrived_at_idx').on(t.orgId, t.studentId, t.arrivedAt),
    check('clinic_visits_person', sql`num_nonnulls(${t.studentId}, ${t.staffId}) >= 1`),
  ],
);

/** A parent's instruction to give a child a medicine at school. */
export const medicationPlans = defineTable(
  'medication_plans',
  {
    module: 'M34',
    scope: 'branch',
    cap: 'health',
    family: 'studentId',
    familyRule: { read: true, insert: { status: 'requested' } },
  },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    studentId: uuid()
      .references((): AnyPgColumn => students.id)
      .notNull(),
    medicine: text().notNull(),
    dose: text().notNull(),
    /** "10:30", "after lunch" */
    times: text().array().notNull(),
    fromDate: dateStr().notNull(),
    toDate: dateStr().notNull(),
    prescriptionFileId: uuid().references((): AnyPgColumn => files.id),
    /** the guardian, or the nurse on their behalf */
    requestedBy: uuid()
      .references((): AnyPgColumn => profiles.id)
      .notNull(),
    status: enumText(medicationPlanStatuses).notNull().default('requested'),
    decidedBy: uuid().references((): AnyPgColumn => profiles.id),
    note: text(),
  },
  (t) => [check('medication_plans_to_date_from', sql`${t.toDate} >= ${t.fromDate}`)],
);

export const medicationLog = defineTable(
  'medication_log',
  {
    module: 'M34',
    scope: 'branch',
    cap: 'health',
    capOwner: 'staffId',
    family: 'studentId',
    appendOnly: true,
    staff: 'append',
  },
  {
    ...appendColumns,
    branchId: branchIdColumn(),
    studentId: uuid().references((): AnyPgColumn => students.id),
    staffId: uuid().references((): AnyPgColumn => staff.id),
    planId: uuid().references((): AnyPgColumn => medicationPlans.id),
    visitId: uuid().references((): AnyPgColumn => clinicVisits.id),
    medicine: text().notNull(),
    dose: text().notNull(),
    givenAt: timestamptz().notNull(),
    givenBy: uuid()
      .references((): AnyPgColumn => profiles.id)
      .notNull(),
    /** when it came from clinic stock */
    itemId: uuid().references((): AnyPgColumn => inventoryItems.id),
    note: text(),
  },
);

/** A vaccination drive or a screening camp. */
export const healthCampaigns = defineTable(
  'health_campaigns',
  {
    module: 'M34',
    scope: 'branch',
    member: { read: { status: ['consent_open', 'in_progress', 'completed'] } },
  },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    /** "Typhoid vaccination, October 2026" */
    name: text().notNull(),
    kind: enumText(healthCampaignKinds).notNull(),
    heldOn: dateStr().notNull(),
    endsOn: dateStr(),
    /** empty means all */
    gradeIds: uuid()
      .array()
      .notNull()
      .default(sql`'{}'`),
    /** the health department or a partner clinic */
    provider: text(),
    consentRequired: boolean().notNull().default(true),
    consentDueOn: dateStr(),
    /** what the parent reads */
    details: text(),
    status: enumText(healthCampaignStatuses).notNull().default('planned'),
  },
);

export const healthConsents = defineTable(
  'health_consents',
  { module: 'M34', scope: 'branch', family: 'studentId', familyRule: { read: true, update: true } },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    campaignId: uuid()
      .references((): AnyPgColumn => healthCampaigns.id)
      .notNull(),
    studentId: uuid()
      .references((): AnyPgColumn => students.id)
      .notNull(),
    decision: enumText(healthConsentDecisions).notNull().default('pending'),
    /** the guardian, or staff recording a signed paper form */
    decidedBy: uuid().references((): AnyPgColumn => profiles.id),
    decidedAt: timestamptz(),
    paperFormFileId: uuid().references((): AnyPgColumn => files.id),
    note: text(),
  },
  (t) => [
    uniqueIndex('health_consents_campaign_student_uq').on(t.campaignId, t.studentId).where(live(t)),
  ],
);

export const vaccinations = defineTable(
  'vaccinations',
  { module: 'M34', scope: 'org', cap: 'health', family: 'studentId' },
  {
    ...baseColumns,
    studentId: uuid()
      .references((): AnyPgColumn => students.id)
      .notNull(),
    vaccine: text().notNull(),
    doseNo: integer().notNull().default(1),
    /** not in the future */
    givenOn: dateStr().notNull(),
    campaignId: uuid().references((): AnyPgColumn => healthCampaigns.id),
    source: enumText(vaccinationSources).notNull(),
    batchNo: text(),
    givenBy: text(),
    nextDueOn: dateStr(),
    /** a photo of the vaccination card */
    cardFileId: uuid().references((): AnyPgColumn => files.id),
  },
  (t) => [
    uniqueIndex('vaccinations_student_vaccine_dose_no_uq')
      .on(t.studentId, t.vaccine, t.doseNo)
      .where(live(t)),
  ],
);

export const healthScreenings = defineTable(
  'health_screenings',
  { module: 'M34', scope: 'branch', cap: 'health', family: 'studentId' },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    studentId: uuid()
      .references((): AnyPgColumn => students.id)
      .notNull(),
    campaignId: uuid().references((): AnyPgColumn => healthCampaigns.id),
    screenedOn: dateStr().notNull(),
    heightCm: decimal(5, 1),
    weightKg: decimal(5, 1),
    /** generated from height and weight */
    bmi: decimal(4, 1).generatedAlwaysAs(
      (): SQL =>
        sql`round(${healthScreenings.weightKg} / ((${healthScreenings.heightCm} / 100.0) * (${healthScreenings.heightCm} / 100.0)), 1)`,
    ),
    /** "6/6" */
    visionLeft: text(),
    visionRight: text(),
    hearing: enumText(healthScreeningHearings),
    dental: enumText(healthScreeningDentals),
    findings: text(),
    needsReferral: boolean().notNull().default(false),
    /** what the parent is asked to do */
    referralNote: text(),
    screenedBy: text(),
  },
  (t) => [
    between('health_screenings', t.heightCm, 50, 220),
    between('health_screenings', t.weightKg, 8, 200),
    uniqueIndex('health_screenings_student_campaign_uq')
      .on(t.studentId, t.campaignId)
      .where(sql`${t.deletedAt} is null and ${t.campaignId} is not null`),
  ],
);

/** An accident or injury. Any staff member can file one, so it is not behind the capability; it holds what happened, not medical history. */
export const incidentReports = defineTable(
  'incident_reports',
  { module: 'M34', scope: 'branch', family: 'studentId' },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    /** from the `incident` sequence */
    incidentNo: text().notNull(),
    studentId: uuid().references((): AnyPgColumn => students.id),
    staffId: uuid().references((): AnyPgColumn => staff.id),
    /** not in the future */
    occurredAt: timestamptz().notNull(),
    place: text().notNull(),
    kind: enumText(incidentReportKinds).notNull(),
    severity: enumText(incidentReportSeverities).notNull(),
    description: text().notNull(),
    firstAid: text(),
    witnesses: text(),
    reportedBy: uuid()
      .references((): AnyPgColumn => profiles.id)
      .notNull(),
    visitId: uuid().references((): AnyPgColumn => clinicVisits.id),
    guardianInformedAt: timestamptz(),
    /** what the family sees */
    guardianSummary: text(),
    followUp: text(),
    status: enumText(incidentReportStatuses).notNull().default('open'),
    reviewedBy: uuid().references((): AnyPgColumn => profiles.id),
  },
);
